struct CanvasResizeDraftValue {int width=1,height=1,offsetX=0,offsetY=0;bool operator==(const CanvasResizeDraftValue& b)const{return width==b.width&&height==b.height&&offsetX==b.offsetX&&offsetY==b.offsetY;}};
class CanvasResizeDraft {
 int originalW_,originalH_;std::vector<CanvasResizeDraftValue> undo_,redo_;std::string group_;
 static int safe(double n){return int(std::clamp(n,double(std::numeric_limits<int>::min()),double(std::numeric_limits<int>::max())));}
public:
 CanvasResizeDraftValue value;CanvasAnchor anchor=CanvasAnchor::Center;bool ratio=true,syncEdges=false,trimOutside=true;
 CanvasResizeDraft(int w,int h):originalW_(w),originalH_(h),value{w,h,0,0}{}
 int originalWidth()const{return originalW_;}int originalHeight()const{return originalH_;}
 void finish(){group_.clear();}
 bool set(CanvasResizeDraftValue next,const std::string& group){if(next==value)return false;if(group_.empty()||group_!=group)undo_.push_back(value);group_=group;redo_.clear();value=next;return true;}
 bool undo(){finish();if(undo_.empty())return false;redo_.push_back(value);value=undo_.back();undo_.pop_back();return true;}
 bool redo(){finish();if(redo_.empty())return false;undo_.push_back(value);value=redo_.back();redo_.pop_back();return true;}
 bool selectAnchor(CanvasAnchor a){finish();anchor=a;auto next=value;const auto off=canvasResizeOffset(originalW_,originalH_,next.width,next.height,a);next.offsetX=off.x;next.offsetY=off.y;const bool changed=set(next,"anchor");finish();return changed;}
 bool dimension(int axis,double raw){auto next=value;const int n=std::clamp(safe(std::floor(raw)),1,1024);if(axis==0){next.width=n;if(ratio)next.height=std::max(1,safe(std::floor(double(n)*originalH_/originalW_+.5)));}else{next.height=n;if(ratio)next.width=std::max(1,safe(std::floor(double(n)*originalW_/originalH_+.5)));}const auto off=canvasResizeOffset(originalW_,originalH_,next.width,next.height,anchor);next.offsetX=off.x;next.offsetY=off.y;return set(next,axis==0?"dimension-width":"dimension-height");}
 std::array<int,4> edges()const{return {value.offsetX,value.offsetY,safe(double(value.width)-originalW_-value.offsetX),safe(double(value.height)-originalH_-value.offsetY)};}
 bool edge(int edge,double raw){const auto old=edges();int n=safe(std::trunc(raw));auto next=value;if(syncEdges){const int minimum=std::max(int(std::ceil((1.-originalW_)/2)),int(std::ceil((1.-originalH_)/2)));n=std::max(n,minimum);next={safe(double(originalW_)+2.*n),safe(double(originalH_)+2.*n),n,n};}else{if(edge==0){next.width=std::max(1,safe(double(originalW_)+n+old[2]));next.offsetX=n;}if(edge==1){next.height=std::max(1,safe(double(originalH_)+n+old[3]));next.offsetY=n;}if(edge==2)next.width=std::max(1,safe(double(originalW_)+old[0]+n));if(edge==3)next.height=std::max(1,safe(double(originalH_)+old[1]+n));}return set(next,syncEdges?"edge-synced":"edge-"+std::to_string(edge));}
 bool valid()const{return value.width>=1&&value.width<=1024&&value.height>=1&&value.height<=1024;}
};
