 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();const int w=r.w/uiScale,h=r.h/uiScale;auto place=[&](ui::Widget* c,int x,int y,int cw,int ch){c->setBounds({r.x+x*uiScale,r.y+y*uiScale,cw*uiScale,ch*uiScale});};layoutHeaderButton(close_);const int half=(w-36)/2;place(numbers_[0],6,39,half,textControlHeight);place(lock_,8+half,39,20,textControlHeight);place(numbers_[1],30+half,39,w-36-half,textControlHeight);const int ax=(w-64)/2;for(int i=0;i<9;++i)place(anchors_[i],ax+(i%3)*21,77+(i/3)*21,22,22);const int edgeWidth=(w-14)/2;for(int i=0;i<4;++i)place(numbers_[i+2],6+(i%2)*(edgeWidth+2),159+(i/2)*38,edgeWidth,textControlHeight);place(sync_,6,223,w-12,textControlHeight);place(trim_,6,245,w-34,textControlHeight);place(trimInfo_,w-26,245,20,textControlHeight);place(cancel_,w-120,DialogLayout::footer(h),55,textControlHeight);place(done_,w-63,DialogLayout::footer(h),57,textControlHeight);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"调整画布尺寸");auto text=[&](const char32_t* s,int x,int y){font_.draw(g,s,r.x+x,r.y+y,skin_["text"]);};text(U"宽",6,27);text(U"高",30+(r.w-36)/2,27);text(U"锚点",6,65);text(U"左",6,147);text(U"上",8+(r.w-14)/2,147);text(U"右",6,185);text(U"下",8+(r.w-14)/2,185);if(!error_.empty()){g.saveClip();g.clipRect({r.x+6,r.y+271,r.w-12,12});font_.draw(g,error_,r.x+6,r.y+271,skin_["text"]);g.restoreClip();}}
